const _T = x => (window.DD_TR && window.DD_TR(x)) || x;
const _DAYS = { Mondays: "Senin", Tuesdays: "Selasa", Wednesdays: "Rabu", Thursdays: "Kamis", Fridays: "Jumat", Saturdays: "Sabtu", Sundays: "Minggu" };
const _days = s => s.replace(/\b(Mondays|Tuesdays|Wednesdays|Thursdays|Fridays|Saturdays|Sundays)\b/g, d => _DAYS[d]).replace(/ and /g, " dan ").replace(/, and /g, ", dan ");
const _unit = s => s.replace(/(\d+)\s*hours?\b/g, "$1 jam").replace(/(\d+)\s*hr\b/g, "$1 jam").replace(/(\d+)\s*(?:mins?|minutes?)\b/g, "$1 mnt").replace(/(\d+)\s*days?\b/g, "$1 hari").replace(/(\d+)\s*d\b/g, "$1 hari").replace(/(\d+)\s*sec\b/g, "$1 dtk");
const _clock = s => s.replace(/^(\d{1,2})(?::(\d\d))?\s*(am|pm)$/i, (m, h, mi, ap) => { h = +h % 12 + (/pm/i.test(ap) ? 12 : 0); return (h < 10 ? "0" : "") + h + "." + (mi || "00"); });
const _slot = (a, b) => /am|pm/i.test(a + b) ? _clock(a) + " sampai " + _clock(b) : a + " sampai " + b;
const _TIME = "(\\d{1,2}(?::\\d\\d)?(?:\\s*(?:am|pm))?)";
const _off = s => s.replace(/^(.+?) off$/, "potongan $1");
window.DD_POST = s => s.replace(new RegExp("\\b" + _TIME + " to " + _TIME + "\\b", "gi"), (m, a, b) => _slot(a, b));
